window.SITE_DATA = {"bio": "I am currently a Lecturer in the College of Computer Science and Engineering at Chongqing University of Technology. I have been honoured as Shiji Scholar of Chongqing University of Technology. Before coming to Chongqing University of Technology, I obtained my Ph.D. degree from Nanjing University in 2021. I received my B.S. and M.S. degrees from Chongqing Jiaotong University and Yunnan Minzu University in 2013 and 2017 respectively.", "news": [{"date": "2026.10", "text": "Congratulations to Wenchao Yan and Kaiwen Chen on being selected as candidates for the National Graduate Scholarship in 2026 (研究生国家奖学金).", "images": []}, {"date": "2026.10", "text": "One paper is accepted by ACM Transactions on Multimedia Computing Communications and Applications (SCI,中科院三区, CCF-B).", "images": []}, {"date": "2026.09", "text": "One paper is accepted by Optics & Laser Technology (SCI).", "images": []}, {"date": "2026.09", "text": "Autumn group outing and team-building activities. (2026年9月秋游团建，一起探索自然、增进交流！)", "images": ["assets/falltravel.jpg"]}, {"date": "2026.09", "text": "Warmly welcome our new graduate students joining the group in 2026! (欢迎2026级研究生加入课题组，开启新的学习与科研旅程！)", "images": ["assets/2026new.jpg"]}, {"date": "2026.05", "text": "We joyfully come together to celebrate the graduation of the Class of 2023 postgraduates. (一切过往皆为序章, 祝大家鹏程万里未来可期!)", "images": ["assets/biye2026-1.jpg", "assets/biye2026.jpg"]}, {"date": "2026.05", "text": "Congratulations to Jinhong He on passing his master’s thesis defense. He will pursue his Ph.D. degree at Nanjing University (南京大学) this September.", "images": ["assets/hjh.jpg"]}, {"date": "2026.05", "text": "Congratulations to Shuaibin Fan on passing his master’s thesis defense. He will pursue his Ph.D. degree at Southeast University (东南大学) this September.", "images": ["assets/fsb.jpg"]}, {"date": "2026.05", "text": "Congratulations to Aoxiang Ning for successfully passing his master’s degree thesis defense!", "images": ["assets/nax.jpg"]}, {"date": "2026.05", "text": "One paper is accepted by Neural Networks (SCI, CCF-B).", "images": []}, {"date": "2026.03", "text": "One paper is accepted by The Visual Computer (SCI,中科院三区, CCF-C).", "images": []}, {"date": "2026.03", "text": "Spring group hiking.", "images": ["assets/tuanjian2026.jpg"]}, {"date": "2026.03", "text": "One paper is accepted by ACM Transactions on Multimedia Computing Communications and Applications (SCI,中科院三区, CCF-B).", "images": []}, {"date": "2026.02", "text": "One paper is accepted by CVPR 2026 (CCF-A).", "images": []}, {"date": "2026.02", "text": "One paper is accepted by The Visual Computer (SCI,中科院三区, CCF-C).", "images": []}, {"date": "2026.01", "text": "One paper is accepted by Pattern Recognition Letters (SCI,中科院三区, CCF-C).", "images": []}, {"date": "2025.11", "text": "Two of our students won the second prize, and our won the third prize in the Huawei Cup of National Post-Graduate Mathematical Contest in Modeling. (华为杯研究生数学建模大赛)", "images": ["assets/huawei2025.png"]}, {"date": "2025.10", "text": "One paper is accepted by Signal Processing (SCI,中科院二区,CCF-C).", "images": []}, {"date": "2025.10", "text": "Congratulations to Jinhong He, Shuaibin Fan and Aoxiang Ning are selected as candidates for the National Graduate Scholarship in 2025 (研究生国家奖学金).", "images": ["assets/guojiang2025.jpg"]}, {"date": "2025.09", "text": "Warmly welcome four new students to join us.", "images": ["assets/2025heying.jpg"]}, {"date": "2025.08", "text": "One paper is accepted by ACM Transactions on Multimedia Computing Communications and Applications (SCI,中科院三区, CCF-B).", "images": []}, {"date": "2025.07", "text": "One paper is accepted by ACM MM 2025 (CCF-A).", "images": []}, {"date": "2025.06", "text": "One paper is accepted by Pattern Recognition (SCI,中科院一区, CCF-B).", "images": []}, {"date": "2025.06", "text": "One paper is accepted by ACAIT 2025.", "images": []}, {"date": "2025.06", "text": "One paper is accepted by Pattern Recognition (SCI,中科院一区, CCF-B).", "images": []}, {"date": "2025.06", "text": "One paper is accepted by IEEE Transactions on Multimedia (SCI,中科院一区, CCF-B).", "images": []}, {"date": "2025.05", "text": "Congratulations to Yanyi He and Peiqi Xie for successfully passing their master’s degree thesis defense!", "images": ["assets/2025biye.jpg"]}, {"date": "2025.04", "text": "One paper is accepted by IJCNN 2025 (CCF-C).", "images": []}, {"date": "2025.03", "text": "One paper is accepted by The Visual Computer (SCI,中科院三区, CCF-C).", "images": []}, {"date": "2025.03", "text": "Spring group hiking.", "images": ["assets/2025spring.jpg"]}, {"date": "2025.02", "text": "Two papers are accepted by IEEE Signal Processing Letters (SCI,中科院二区, CCF-C).", "images": []}, {"date": "2025.01", "text": "One paper is accepted by Pattern Recognition Letters (SCI,中科院三区, CCF-C).", "images": []}, {"date": "2025.01", "text": "Jianfeng Fu and Kaiwen Chen conducted a study tour at the Royal Institute of Technology in Thailand.", "images": ["assets/2025Thai.jpg"]}, {"date": "2024.12", "text": "One paper is accepted by the International Journal of Pattern Recognition and Artificial Intelligence  (SCI,中科院四区, CCF-C).", "images": []}, {"date": "2024.12", "text": "Minglong Xue and Jinhong He attended ACML2024 in Hanoi, Vietnam.", "images": ["assets/acml.jpg"]}, {"date": "2024.11", "text": "Five of our students won the second prize, and two won the third prize in the Huawei Cup of National Post-Graduate Mathematical Contest in Modeling. (华为杯研究生数学建模大赛)", "images": ["assets/huawei2024.jpg"]}, {"date": "2024.11", "text": "Minglong Xue and Jinhong He attended ACAIT2024 in Fuzhou, China.", "images": ["assets/acait.jpg"]}, {"date": "2024.10", "text": "One paper is accepted by Expert Systems with Applications (SCI,中科院一区).", "images": []}, {"date": "2024.10", "text": "Yanyi He and Shuaibin Fan are selected as candidates for the National Graduate Scholarship in 2024 (研究生国家奖学金).", "images": ["assets/guojiang2024.jpg"]}, {"date": "2024.09", "text": "Warmly welcome three new graduate students to join us.", "images": ["assets/2024.jpg"]}, {"date": "2024.09", "text": "One paper is accepted by ACML 2024 (CCF-C).", "images": []}, {"date": "2024.08", "text": "One paper is accepted by ICPR 2024 (CCF-C).", "images": []}, {"date": "2024.07", "text": "One paper is accepted by the IEEE Signal Processing Letters (SCI,中科院二区,CCF-C).", "images": []}, {"date": "2024.03", "text": "Team-building activities.", "images": ["assets/team_building.jpg"]}, {"date": "2024.02", "text": "Peiqi Xie conducted a study tour at the Royal Institute of Technology in Thailand.", "images": ["assets/Xiepeiqi_visiting.jpg"]}, {"date": "2023 12", "text": "Five of our students won the third prize in the Huawei Cup of National Post-Graduate Mathematical Contest in Modeling. (华为杯研究生数学建模大赛)", "images": []}, {"date": "2023.11", "text": "One paper is accepted by the Journal of Cloud Computing (SCI,中科院三区).", "images": []}, {"date": "2023.10", "text": "Zhengyang He attended ICIP2023 in Kuala Lumpur, Malaysia.", "images": ["assets/hezhengyang202310.png"]}, {"date": "2023.09", "text": "2023.09  Warmly welcome three new graduate students to join us.", "images": ["assets/team202309.png"]}, {"date": "2023.06", "text": "One paper is accepted by ICIP2023 (CCF-C).", "images": []}], "publications": [{"year": "2026", "html": "[ACM TOMM] Xue M, Qu Y, Ning A, Zhong S and Zhou M. DFDNet: Dynamic Frequency-Guided De-Flare Network. ACM Transactions on Multimedia Computing, Communications, and Applications, 2026 (accepted, SCI, CCF-B). <a href=\"https://arxiv.org/abs/2507.17489\">[Paper]</a> <a href=\"https://github.com/AXNing/DFDNet\">[Code]</a>", "text": "[ACM TOMM] Xue M, Qu Y, Ning A, Zhong S and Zhou M. DFDNet: Dynamic Frequency-Guided De-Flare Network. ACM Transactions on Multimedia Computing, Communications, and Applications, 2026 (accepted, SCI, CCF-B).", "image": "assets/publications/dfdnet.webp", "imageSource": "https://github.com/AXNing/DFDNet", "imageAlt": "Overall framework of DFDNet", "abstractEn": "DFDNet separates flare artifacts from image content in the frequency domain. Dynamic global frequency guidance suppresses large flares, while contrastive local detail guidance helps restore structures around light sources. The method addresses both broad flare contamination and the loss of fine details during restoration.", "abstractZh": "DFDNet 在频域中分离眩光与图像内容，利用动态全局频域引导抑制大范围眩光，并通过对比学习引导局部细节恢复。该方法兼顾大面积眩光消除与光源附近的结构保留，减少修复过程中的细节损失。", "title": "DFDNet: Dynamic Frequency-Guided De-Flare Network"}, {"year": "2026", "html": "[Optics & Laser Technology] Fan S, Yan W, Xue M, Shivakumara P and Lu T. FM-Dehaze: Fine-grained modeling of non-uniform haze degradation for unpaired image dehazing. Optics & Laser Technology, 204, Part E, 116385, 2026. <a href=\"https://doi.org/10.1016/j.optlastec.2026.116385\">[Paper]</a> <a href=\"https://github.com/Fan-pixel/FM-Dehaze\">[Code]</a>", "text": "[Optics & Laser Technology] Fan S, Yan W, Xue M, Shivakumara P and Lu T. FM-Dehaze: Fine-grained modeling of non-uniform haze degradation for unpaired image dehazing. Optics & Laser Technology, 204, Part E, 116385, 2026.", "image": "assets/publications/paper-0.webp", "imageSource": "https://raw.githubusercontent.com/Fan-pixel/FM-Dehaze/main/Frame.png", "imageAlt": "Representative figure from [Optics & Laser Technology] Shuaibin Fan, Wenchao Yan, Minglong Xue, Shivakumara Palaiahnakote, Tong Lu. FM-Dehaze: Fine-grained modeling of non-uniform haze degradation for unpaired image dehazing. Optics & Laser Technology, 204, Part E, 116385, 2026.", "publicationDate": "2026.12", "publicationDateType": "issue", "publicationDateSource": "https://api.crossref.org/works/10.1016/j.optlastec.2026.116385", "abstractEn": "FM-Dehaze models spatially varying haze using collaborative dual-branch nonlinear representations and implicit neural representations. Coordinate-based degradation modeling captures local haze intensity, while dense residual enhancement progressively recovers image details. The framework targets unpaired dehazing with more consistent restoration across non-uniform haze regions.", "abstractZh": "FM-Dehaze 结合协同双分支非线性表征与隐式神经表示，对空间分布不均匀的雾退化进行细粒度建模。基于坐标的连续退化表示刻画局部雾强度，密集残差增强逐步恢复细节，从而改善非配对去雾中的局部恢复与全局一致性。", "title": "FM-Dehaze: Fine-grained modeling of non-uniform haze degradation for unpaired image dehazing"}, {"year": "2026", "html": "[Neural Networks]  Ning A, Xue M, Zhong S, et al. Better Utilization of Illumination Prior via KANs for Nighttime Flare Removal[J]. Neural Networks, 2026: 109138. (SCI, CCF-B). <a href=\"https://www.sciencedirect.com/science/article/pii/S089360802600599X\">[Paper]</a> <a href=\"https://github.com/AXNing/Illumination-Guided-Frequency-Adaptive-Network\">[Code]</a>", "text": "[Neural Networks]  Ning A, Xue M, Zhong S, et al. Better Utilization of Illumination Prior via KANs for Nighttime Flare Removal[J]. Neural Networks, 2026: 109138. (SCI, CCF-B). [Paper] [Code]", "image": "assets/publications/paper-1.webp", "imageSource": "https://raw.githubusercontent.com/AXNing/Illumination-Guided-Frequency-Adaptive-Network/main/framework.jpg", "imageAlt": "Representative figure from [Neural Networks]  Ning A, Xue M, Zhong S, et al. Better Utilization of Illumination Prior via KANs for Nighttime Flare Removal[J]. Neural Networks, 2026: 109138. (SCI, CCF-B). [Paper] [Code]", "publicationDate": "2026.11", "publicationDateType": "issue", "publicationDateSource": "https://api.crossref.org/works/10.1016/j.neunet.2026.109138", "abstractEn": "This method uses Kolmogorov–Arnold networks to learn nonlinear illumination priors and adaptively adjust feature frequency components. Illumination-guided enhancement and suppression help distinguish flare from scene content. A frequency-band swapping strategy provides synthetic training supervision intended to better reflect the relationship between illumination and flare.", "abstractZh": "该方法通过 Kolmogorov–Arnold 网络学习非线性光照先验，并据此自适应调整特征的频率成分。光照引导的增强与抑制有助于分离眩光和场景内容；频带交换的数据合成策略进一步改善训练监督，使其更好地反映光照与眩光之间的关系。", "title": "Better Utilization of Illumination Prior via KANs for Nighttime Flare Removal"}, {"year": "2026", "html": "[The Visual Computer] Xue M, Shang X, He J and Zhong S. Wavelet Transform-Guided Transformer Light Transfer Network for Zero-Shot Low-Light Image Enhancement, The Visual Computer, 2026. (SCI, 中科院三区).  <a href=\"https://link.springer.com/article/10.1007/s00371-026-04471-5\">[Paper]</a> <a href=\"\">[Code]</a>", "text": "[The Visual Computer] Xue M, Shang X, He J and Zhong S. Wavelet Transform-Guided Transformer Light Transfer Network for Zero-Shot Low-Light Image Enhancement, The Visual Computer, 2026. (SCI, 中科院三区). [Paper] [Code]", "image": "assets/publications/paper-2.webp", "imageSource": "https://raw.githubusercontent.com/sxk2137/Wavelet/main/framework.png", "imageAlt": "Representative figure from [The Visual Computer] Xue M, Shang X, He J and Zhong S. Wavelet Transform-Guided Transformer Light Transfer Network for Zero-Shot Low-Light Image Enhancement, The Visual Computer, 2026. (SCI, 中科院三区). [Paper] [Code]", "publicationDate": "2026.05", "publicationDateType": "online", "publicationDateSource": "https://api.crossref.org/works/10.1007/s00371-026-04471-5", "abstractEn": "This zero-reference enhancement method combines Retinex-based initial illumination recovery with a Transformer light transfer network. Multi-level wavelet decomposition supplies low-frequency illumination information, while the initially enhanced image provides content structures. The approach reduces reliance on well-lit training references and adapts enhancement to the input image.", "abstractZh": "该零参考低光照增强方法将 Retinex 初始光照恢复与 Transformer 光照迁移网络结合。多级小波分解提供低频光照信息，初步增强图像提供内容结构，在降低对正常光照参考图像依赖的同时，实现面向输入场景的自适应增强。", "title": "Wavelet Transform-Guided Transformer Light Transfer Network for Zero-Shot Low-Light Image Enhancement"}, {"year": "2026", "html": "[ACM TOMM] Xue M, Fan S, Yan W and Zhou M. Unsupervised Dehazing of Real-World Images with Frequency-Aware Learning [J]. ACM Transactions on Multimedia Computing Communications and Applications, 2026 ( SCI, CCF-B). <a href=\"https://dl.acm.org/doi/full/10.1145/3803423\">[Paper]</a> <a href=\"https://github.com/Fan-pixel/FAL-Net\">[Code]</a>", "text": "[ACM TOMM] Xue M, Fan S, Yan W and Zhou M. Unsupervised Dehazing of Real-World Images with Frequency-Aware Learning [J]. ACM Transactions on Multimedia Computing Communications and Applications, 2026 ( SCI, CCF-B). [Paper] [Code]", "image": "assets/publications/paper-3.webp", "imageSource": "https://raw.githubusercontent.com/Fan-pixel/FAL-Net/main/Frame.png", "imageAlt": "Representative figure from [ACM TOMM] Xue M, Fan S, Yan W and Zhou M. Unsupervised Dehazing of Real-World Images with Frequency-Aware Learning [J]. ACM Transactions on Multimedia Computing Communications and Applications, 2026 ( SCI, CCF-B). [Paper] [Code]", "publicationDate": "2026.04", "publicationDateType": "online", "publicationDateSource": "https://api.crossref.org/works/10.1145/3803423", "abstractEn": "FAL-Net addresses unsupervised real-world dehazing through frequency-aware learning. Content-aware state-space modeling enhances contextual and high-frequency information, haze-density guidance supports adaptive expert fusion, and contour-guided frequency recovery helps retain image structures. These components jointly target detail preservation under complex haze degradation.", "abstractZh": "FAL-Net 通过频率感知学习解决真实场景的无监督去雾问题。内容感知状态空间建模增强上下文与高频信息，雾密度引导支持自适应专家融合，轮廓引导的频率恢复帮助保留结构，协同改善复杂雾退化下的细节恢复。", "title": "Unsupervised Dehazing of Real-World Images with Frequency-Aware Learning"}, {"year": "2026", "html": "[CVPR 2026]  Ning A, Yu K, Xue M*, et al. Language-Guided One-Step Diffusion Model for Nighttime Flare Removal, Proceedings of the IEEE/CVF International Conference on Computer Vision and Pattern Recognition, 2026. (to accept, CCF-A)", "text": "[CVPR 2026]  Ning A, Yu K, Xue M*, et al. Language-Guided One-Step Diffusion Model for Nighttime Flare Removal, Proceedings of the IEEE/CVF International Conference on Computer Vision and Pattern Recognition, 2026. (to accept, CCF-A)", "image": "assets/publications/paper-4.webp", "imageSource": "https://openaccess.thecvf.com/content/CVPR2026/papers/Ning_Language-Guided_One-Step_Diffusion_Model_for_Nighttime_Flare_Removal_CVPR_2026_paper.pdf", "imageAlt": "Representative figure from [CVPR 2026]  Ning A, Yu K, Xue M*, et al. Language-Guided One-Step Diffusion Model for Nighttime Flare Removal, Proceedings of the IEEE/CVF International Conference on Computer Vision and Pattern Recognition, 2026. (to accept, CCF-A)", "abstractEn": "Flare-VLM uses language guidance to support nighttime flare removal with a one-step diffusion model. Text descriptions inform restoration, while semantic distribution distillation transfers generative guidance to efficient inference. Instruction-driven sample synthesis supplies training examples for removing flare while retaining scene content.", "abstractZh": "Flare-VLM 将语言引导引入夜间眩光去除，并采用一步扩散模型提高推理效率。文本描述辅助恢复，语义分布蒸馏传递生成先验，指令驱动的样本合成提供训练数据，以兼顾眩光抑制与场景内容保留。", "title": "Language-Guided One-Step Diffusion Model for Nighttime Flare Removal"}, {"year": "2026", "html": "[The Visual Computer] Xue M, Chen K, et al. Dynamic Nonlinear Networks for Adaptive Low-Light Image Enhancement, The Visual Computer,2026. (SCI, 中科院三区).<a href=\"https://link.springer.com/article/10.1007/s00371-026-04410-4\">[Paper]</a> <a href=\"https://github.com/KKKKevin0401/DEFE\">[Code]</a>", "text": "[The Visual Computer] Xue M, Chen K, et al. Dynamic Nonlinear Networks for Adaptive Low-Light Image Enhancement, The Visual Computer,2026. (SCI, 中科院三区). [Paper] [Code]", "image": "assets/publications/paper-5.webp", "imageSource": "https://raw.githubusercontent.com/KKKKevin0401/DEFE/main/structure.png", "imageAlt": "Representative figure from [The Visual Computer] Xue M, Chen K, et al. Dynamic Nonlinear Networks for Adaptive Low-Light Image Enhancement, The Visual Computer,2026. (SCI, 中科院三区). [Paper] [Code]", "publicationDate": "2026.03", "publicationDateType": "online", "publicationDateSource": "https://api.crossref.org/works/10.1007/s00371-026-04410-4", "abstractEn": "This low-light enhancement framework uses dynamic nonlinear networks to adapt to image degradation. A dynamic edge feature extractor provides structural guidance, while edge-preserving constraints and residual refinement help recover illumination and details. The design aims to handle varying low-light conditions without losing important image boundaries.", "abstractZh": "该低光照增强框架利用动态非线性网络适应不同图像退化。动态边缘特征提取提供结构引导，结合边缘保持约束与残差细化，改善光照和细节恢复，并减少增强过程中重要边界信息的损失。", "title": "Dynamic Nonlinear Networks for Adaptive Low-Light Image Enhancement"}, {"year": "2026", "html": "[PRL] Xue M, Ning A et al. Nighttime Flare Removal via Frequency Decoupling, Pattern Recognition Letters, 2026. (SCI, 中科院三区).<a href=\"https://doi.org/10.1016/j.patrec.2026.01.012\">[Paper]</a>", "text": "[PRL] Xue M, Ning A et al. Nighttime Flare Removal via Frequency Decoupling, Pattern Recognition Letters, 2026. (SCI, 中科院三区). [Paper]", "image": "assets/publications/nighttime-frequency-decoupling.jpg", "imageAlt": "Nighttime Flare Removal via Frequency Decoupling: object detection and semantic segmentation comparisons", "imageSource": "https://doi.org/10.1016/j.patrec.2026.01.012", "publicationDate": "2026.03", "publicationDateType": "issue", "publicationDateSource": "https://api.crossref.org/works/10.1016/j.patrec.2026.01.012", "abstractEn": "This flare-removal method decouples frequency components to distinguish broad flare interference from image structures. A frequency decoupling module learns how to separate these signals, and frequency fusion combines amplitude and phase information for restoration. The approach seeks to suppress brightness distortion while preserving structural details.", "abstractZh": "该眩光去除方法通过频率解耦区分大范围眩光干扰与图像结构。频率解耦模块学习信号分离，频率融合结合幅度和相位信息进行恢复，在抑制亮度失真的同时保留场景细节。", "title": "Nighttime Flare Removal via Frequency Decoupling"}, {"year": "2025", "html": "[SP]  Yan W, Xue M*, Shivakumara P, et al. DFCCNet: Unified Dual-domain Fusion and Color-aware Residual Correction for Robust Single Image Dehazing [J]. Signal Processing,110360,2025. (SCI, 中科院二区) <a href=\"https://doi.org/10.1016/j.sigpro.2025.110360\">[Paper]</a> <a href=\"https://github.com/wenchao-tech/DFCCNet-main\">[Code]</a>", "text": "[SP]  Yan W, Xue M*, Shivakumara P, et al. DFCCNet: Unified Dual-domain Fusion and Color-aware Residual Correction for Robust Single Image Dehazing [J]. Signal Processing,110360,2025. (SCI, 中科院二区) [Paper] [Code]", "image": "assets/publications/dfccnet-results.webp", "imageSource": "https://raw.githubusercontent.com/wenchao-tech/DFCCNet-main/main/images/outdoor.png", "imageAlt": "DFCCNet — representative results from the authors’ project", "publicationDate": "2026.03", "publicationDateType": "issue", "publicationDateSource": "https://api.crossref.org/works/10.1016/j.sigpro.2025.110360", "abstractEn": "DFCCNet combines spatial and wavelet-domain features for robust single-image dehazing. Haze-related guidance supports dual-domain fusion, while color-aware residual correction adjusts color distortions introduced during restoration. Adaptive feature integration aims to improve both haze removal and the natural appearance of recovered images.", "abstractZh": "DFCCNet 融合空间域与小波域特征，实现鲁棒的单幅图像去雾。雾相关先验辅助双域融合，颜色感知残差校正修正恢复中的色彩偏差，自适应特征整合兼顾去雾效果与结果的自然观感。", "title": "DFCCNet: Unified Dual-domain Fusion and Color-aware Residual Correction for Robust Single Image Dehazing"}, {"year": "2025", "html": "[ACM TOMM] Xue M, He J, Wang W and Zhou M. Low-light image enhancement via clip-fourier guided wavelet diffusion[J]. ACM Transactions on Multimedia Computing Communications and Applications, 2025  (SCI, CCF-B). <a href=\"https://dl.acm.org/doi/10.1145/3764933\">[Paper]</a> <a href=\"https://github.com/hejh8/CFWD\">[Code]</a>", "text": "[ACM TOMM] Xue M, He J, Wang W and Zhou M. Low-light image enhancement via clip-fourier guided wavelet diffusion[J]. ACM Transactions on Multimedia Computing Communications and Applications, 2025  (SCI, CCF-B). [Paper] [Code]", "image": "assets/publications/paper-8.webp", "imageSource": "https://raw.githubusercontent.com/hejh8/CFWD/main/Figs/fig2.png", "imageAlt": "Representative figure from [ACM TOMM] Xue M, He J, Wang W and Zhou M. Low-light image enhancement via clip-fourier guided wavelet diffusion[J]. ACM Transactions on Multimedia Computing Communications and Applications, 2025  (SCI, CCF-B). [Paper] [Code]", "publicationDate": "2025.11", "publicationDateType": "online", "publicationDateSource": "https://api.crossref.org/works/10.1145/3764933", "abstractEn": "CFWD combines CLIP semantic guidance with wavelet-domain diffusion for low-light enhancement. Multi-scale supervision supports reconstruction across frequency levels, while Fourier-based high-frequency perception helps recover structures and textures. The framework coordinates semantic information and frequency-domain modeling to improve perceptual image quality.", "abstractZh": "CFWD 将 CLIP 语义引导与小波域扩散结合，用于低光照图像增强。多尺度监督辅助不同频率层级的重建，基于傅里叶的高频感知帮助恢复结构和纹理，使语义信息与频域建模协同改善图像观感。", "title": "Low-light image enhancement via clip-fourier guided wavelet diffusion"}, {"year": "2025", "html": "[ACM MM 2025] He J, Xue M*, Liu Z, et al. Degradation-Consistent Learning via Bidirectional Diffusion for Low-Light Image Enhancement, ACM conference on Multimedia 2025 (CCF-A). <a href=\"https://dl.acm.org/doi/10.1145/3746027.3754496\">[Paper]</a> <a href=\"https://github.com/hejh8/BidDiff\">[Code]</a>", "text": "[ACM MM 2025] He J, Xue M*, Liu Z, et al. Degradation-Consistent Learning via Bidirectional Diffusion for Low-Light Image Enhancement, ACM conference on Multimedia 2025 (CCF-A). [Paper] [Code]", "image": "assets/publications/paper-9.webp", "imageSource": "https://raw.githubusercontent.com/hejh8/BidDiff/main/Fig1.png", "imageAlt": "Representative figure from [ACM MM 2025] He J, Xue M*, Liu Z, et al. Degradation-Consistent Learning via Bidirectional Diffusion for Low-Light Image Enhancement, ACM conference on Multimedia 2025 (CCF-A). [Paper] [Code]", "publicationDate": "2025.10", "publicationDateType": "online", "publicationDateSource": "https://api.crossref.org/works/10.1145/3746027.3754496", "abstractEn": "BidDiff learns low-light enhancement through bidirectional diffusion between low-light and normal-light domains. Modeling both directions encourages degradation-consistent reconstruction. Adaptive feature interaction and reflection-aware color correction help preserve image content and reduce overexposure or color imbalance in the enhanced output.", "abstractZh": "BidDiff 在低光照与正常光照域之间进行双向扩散学习，以双向建模促进退化一致的重建。自适应特征交互与反射感知颜色校正帮助保留内容，并减少增强结果中的过曝和色彩失衡。", "title": "Degradation-Consistent Learning via Bidirectional Diffusion for Low-Light Image Enhancement"}, {"year": "2025", "html": "[PR]  Xue M, He J, Palaiahnakote S, et al. Unified Image Restoration and Enhancement: Degradation Calibrated Cycle Reconstruction Diffusion Model[J]. Pattern Recognition,2025. (SCI, 中科院一区) <a href=\"https://www.sciencedirect.com/science/article/abs/pii/S0031320325007332\">[Paper]</a> <a href=\"https://github.com/hejh8/CycleRDM\">[Code]</a>", "text": "[PR]  Xue M, He J, Palaiahnakote S, et al. Unified Image Restoration and Enhancement: Degradation Calibrated Cycle Reconstruction Diffusion Model[J]. Pattern Recognition,2025. (SCI, 中科院一区) [Paper] [Code]", "image": "assets/publications/paper-10.webp", "imageSource": "https://raw.githubusercontent.com/hejh8/CycleRDM/main/figs/fig1.png", "imageAlt": "Representative figure from [PR]  Xue M, He J, Palaiahnakote S, et al. Unified Image Restoration and Enhancement: Degradation Calibrated Cycle Reconstruction Diffusion Model[J]. Pattern Recognition,2025. (SCI, 中科院一区) [Paper] [Code]", "publicationDate": "2026.03", "publicationDateType": "issue", "publicationDateSource": "https://api.crossref.org/works/10.1016/j.patcog.2025.112073", "abstractEn": "CycleRDM unifies image restoration and enhancement through degradation-calibrated cycle reconstruction. A staged mapping improves degraded inputs before reconstruction, while wavelet calibration and high-frequency feature adjustment control degradation effects. Multimodal prompts and Fourier information guide the diffusion process toward more stable restoration.", "abstractZh": "CycleRDM 通过退化校准的循环重建统一图像恢复与增强。分阶段映射逐步改善退化输入，小波校准与高频特征调整控制退化影响，多模态提示和傅里叶信息共同引导扩散过程，提高恢复稳定性。", "title": "Unified Image Restoration and Enhancement: Degradation Calibrated Cycle Reconstruction Diffusion Model"}, {"year": "2025", "html": "[PR]  Xue M, Fan S, Shivakumara P, et al. UR2P-Dehaze: Learning a Simple Image Dehaze Enhancer via Unpaired Rich Physical Prior[J]. Pattern Recognition,2025. (SCI, 中科院一区) <a href=\"https://doi.org/10.1016/j.patcog.2025.111997\">[Paper]</a> <a href=\"https://github.com/Fan-pixel/UR2P-Dehaze\">[Code]</a>", "text": "[PR]  Xue M, Fan S, Shivakumara P, et al. UR2P-Dehaze: Learning a Simple Image Dehaze Enhancer via Unpaired Rich Physical Prior[J]. Pattern Recognition,2025. (SCI, 中科院一区) [Paper] [Code]", "image": "assets/publications/paper-11.webp", "imageSource": "https://raw.githubusercontent.com/Fan-pixel/UR2P-Dehaze/main/images/Frame.png", "imageAlt": "Representative figure from [PR]  Xue M, Fan S, Shivakumara P, et al. UR2P-Dehaze: Learning a Simple Image Dehaze Enhancer via Unpaired Rich Physical Prior[J]. Pattern Recognition,2025. (SCI, 中科院一区) [Paper] [Code]", "publicationDate": "2026.02", "publicationDateType": "issue", "publicationDateSource": "https://api.crossref.org/works/10.1016/j.patcog.2025.111997", "abstractEn": "UR2P-Dehaze uses unpaired rich physical priors to learn an image dehazing enhancer. Illumination, reflectance and color information provide complementary guidance, while iterative monitoring, dynamic wavelet processing and adaptive color correction refine restoration. The framework addresses haze removal without requiring paired hazy and clear training images.", "abstractZh": "UR2P-Dehaze 利用非配对的丰富物理先验学习去雾增强器。光照、反射与颜色信息提供互补引导，迭代监测、动态小波处理和自适应颜色校正细化恢复，在不依赖成对有雾与清晰训练图像的条件下完成去雾。", "title": "UR2P-Dehaze: Learning a Simple Image Dehaze Enhancer via Unpaired Rich Physical Prior"}, {"year": "2025", "html": "[IEEE TMM]  He J, Xue M*, Wang W, et al. Optimizing a 4D Lookup Table for Low-light Video Enhancement via Wavelet Priori, IEEE Transactions on Multimedia,2025. (SCI, 中科院一区) <a href=\"https://ieeexplore.ieee.org/abstract/document/11329465\">[Paper]</a> <a href=\"https://github.com/hejh8/WaveLUT\">[Code]</a>", "text": "[IEEE TMM]  He J, Xue M*, Wang W, et al. Optimizing a 4D Lookup Table for Low-light Video Enhancement via Wavelet Priori, IEEE Transactions on Multimedia,2025. (SCI, 中科院一区) [Paper] [Code]", "image": "assets/publications/paper-12.webp", "imageSource": "https://raw.githubusercontent.com/hejh8/WaveLUT/main/frame.png", "imageAlt": "Representative figure from [IEEE TMM]  He J, Xue M*, Wang W, et al. Optimizing a 4D Lookup Table for Low-light Video Enhancement via Wavelet Priori, IEEE Transactions on Multimedia,2025. (SCI, 中科院一区) [Paper] [Code]", "abstractEn": "WaveLUT enhances low-light video using a four-dimensional lookup table guided by wavelet priors. Low-frequency information supports illumination and color mapping, while adaptive fusion coordinates appearance recovery. The lookup-table design targets efficient enhancement and improved consistency across video frames.", "abstractZh": "WaveLUT 利用小波先验引导四维查找表，实现低光照视频增强。低频信息辅助光照与颜色映射，自适应融合协调外观恢复，查找表设计兼顾增强效率与视频帧之间的一致性。", "title": "Optimizing a 4D Lookup Table for Low-light Video Enhancement via Wavelet Priori"}, {"year": "2025", "html": "[The Visual Computer] Xie P, Xue M* and Song C. A Novel Half-To-All MOTR Approach for Robust Video Text Tracking with Incomplete Annotations [J]. The Visual Computer, 2025. (SCI, 中科院三区) <a href=\"https://link.springer.com/article/10.1007/s00371-025-03890-0\">[Paper]</a> <a href=\"https://github.com/Paige-Norton/HTAMotr\">[Code]</a>", "text": "[The Visual Computer] Xie P, Xue M* and Song C. A Novel Half-To-All MOTR Approach for Robust Video Text Tracking with Incomplete Annotations [J]. The Visual Computer, 2025. (SCI, 中科院三区) [Paper] [Code]", "image": "assets/publications/htamotr-tracking.webp", "imageSource": "https://raw.githubusercontent.com/Paige-Norton/HTAMotr/master/doc/HTAMotr_Video_156_5_6.gif", "imageAlt": "Half-To-All — representative results from the authors’ project", "publicationDate": "2025.04", "publicationDateType": "online", "publicationDateSource": "https://api.crossref.org/works/10.1007/s00371-025-03890-0", "abstractEn": "HTAMotr addresses video text tracking when annotations are incomplete. Its half-to-all tracking strategy uses rotated queries, proposal-to-ground-truth correlation and overlapping-anchor filtering to improve association. The design seeks to reduce identity switches and make tracking more robust when only part of the text instances is labeled.", "abstractZh": "HTAMotr 面向标注不完整的视频文本跟踪。Half-to-All 跟踪策略结合旋转查询、候选与真值关联以及重叠锚点过滤，改善文本实例匹配，减少身份切换，并增强部分文本实例缺少标注时的跟踪鲁棒性。", "title": "A Novel Half-To-All MOTR Approach for Robust Video Text Tracking with Incomplete Annotations"}, {"year": "2025", "html": "[IEEE SPL] He J, Shivakumara P, Ning A and Xue M*. Zero-Shot Low-Light Image Enhancement via Joint Frequency Domain Priors Guided Diffusion[J]. IEEE Signal Processing Letters, 2025. (SCI, 中科院二区) <a href=\"https://ieeexplore.ieee.org/document/10909219\">[Paper]</a> <a href=\"https://github.com/hejh8/Joint-Wavelet-and-Fourier-priors-guided-diffusion\">[Code]</a>", "text": "[IEEE SPL] He J, Shivakumara P, Ning A and Xue M*. Zero-Shot Low-Light Image Enhancement via Joint Frequency Domain Priors Guided Diffusion[J]. IEEE Signal Processing Letters, 2025. (SCI, 中科院二区) [Paper] [Code]", "image": "assets/publications/paper-14.webp", "imageSource": "https://raw.githubusercontent.com/hejh8/Joint-Wavelet-and-Fourier-priors-guided-diffusion/main/Overview.png", "imageAlt": "Representative figure from [IEEE SPL] He J, Shivakumara P, Ning A and Xue M*. Zero-Shot Low-Light Image Enhancement via Joint Frequency Domain Priors Guided Diffusion[J]. IEEE Signal Processing Letters, 2025. (SCI, 中科院二区) [Paper] [Code]", "abstractEn": "This zero-shot method combines wavelet and Fourier priors to guide low-light enhancement with diffusion. Operating on low-frequency wavelet components supports efficient restoration, while progressive decomposition supplies illumination and structural guidance. The approach reduces dependence on paired low-light training data.", "abstractZh": "该零样本方法结合小波与傅里叶先验，引导扩散模型完成低光照增强。在小波低频成分上进行恢复有助于提高效率，逐步分解提供光照与结构引导，从而降低对配对低光照训练数据的依赖。", "title": "Zero-Shot Low-Light Image Enhancement via Joint Frequency Domain Priors Guided Diffusion"}, {"year": "2025", "html": "[IEEE SPL] Ning A, Xue M*, He J, et al. KAN See In the Dark[J]. IEEE Signal Processing Letters, 2025. (SCI, 中科院二区) <a href=\"https://doi.org/10.1109/LSP.2025.3540700\">[Paper]</a> <a href=\"https://github.com/AXNing/KSID\">[Code]</a>", "text": "[IEEE SPL] Ning A, Xue M*, He J, et al. KAN See In the Dark[J]. IEEE Signal Processing Letters, 2025. (SCI, 中科院二区) [Paper] [Code]", "image": "assets/publications/paper-15.webp", "imageSource": "https://arxiv.org/pdf/2409.03404", "imageAlt": "Representative figure from [IEEE SPL] Ning A, Xue M*, He J, et al. KAN See In the Dark[J]. IEEE Signal Processing Letters, 2025. (SCI, 中科院二区) [Paper] [Code]", "abstractEn": "KAN See In the Dark introduces Kolmogorov–Arnold network blocks with learnable nonlinear functions into low-light enhancement. These blocks model complex relationships caused by uneven illumination and noise. Frequency-domain perception complements the nonlinear representation to improve visually oriented recovery and image details.", "abstractZh": "KAN See In the Dark 将具有可学习非线性函数的 Kolmogorov–Arnold 网络模块引入低光照增强，建模不均匀光照与噪声导致的复杂关系。频域感知进一步补充非线性表征，改善面向视觉质量的恢复与细节表现。", "title": "KAN See In the Dark"}, {"year": "2025", "html": "[PRL] Fan S, Xue M*, Ning A et al. Addressing domain discrepancy: A dual-branch collaborative model to unsupervised dehazing, Pattern Recognition Letters, 2025. (SCI,中科院三区). <a href=\"https://doi.org/10.1016/j.patrec.2025.01.022\">[Paper]</a> <a href=\"https://github.com/Fan-pixel/DCM-dehaze\">[Code]</a>", "text": "[PRL] Fan S, Xue M*, Ning A et al. Addressing domain discrepancy: A dual-branch collaborative model to unsupervised dehazing, Pattern Recognition Letters, 2025. (SCI,中科院三区). [Paper] [Code]", "image": "assets/publications/paper-16.webp", "imageSource": "https://raw.githubusercontent.com/Fan-pixel/DCM-dehaze/main/fig_3.pdf", "imageAlt": "Representative figure from [PRL] Fan S, Xue M*, Ning A et al. Addressing domain discrepancy: A dual-branch collaborative model to unsupervised dehazing, Pattern Recognition Letters, 2025. (SCI,中科院三区). [Paper] [Code]", "publicationDate": "2025.03", "publicationDateType": "issue", "publicationDateSource": "https://api.crossref.org/works/10.1016/j.patrec.2025.01.022", "abstractEn": "This unsupervised dehazing model uses collaborative dehazing and contour branches to address domain discrepancy. Feature extraction and residual enhancement support haze removal, while bidirectional contour constraints help preserve structures. Joint learning aims to reduce the mismatch between training conditions and real-world hazy images.", "abstractZh": "该无监督去雾模型通过去雾与轮廓双分支协同学习缓解域差异。特征提取与残差增强支持雾消除，双向轮廓约束帮助保留结构，联合学习改善训练条件与真实有雾图像之间的分布不匹配。", "title": "Addressing domain discrepancy: A dual-branch collaborative model to unsupervised dehazing"}, {"year": "2025", "html": "[IJPRAI] He Y, He J, Xue M*, Zhong S, and Zhou M, Hybrid-Domain Attention Dense Network For Efficient Image Super-Resolution, International Journal of Pattern Recognition and Artificial Intelligence, 2025.(SCI, 中科院四区). <a href=\"https://doi.org/10.1142/S0218001425540035\">[Paper]</a> <a href=\"https://github.com/Yuii666/HADN\">[Code]</a>", "text": "[IJPRAI] He Y, He J, Xue M*, Zhong S, and Zhou M, Hybrid-Domain Attention Dense Network For Efficient Image Super-Resolution, International Journal of Pattern Recognition and Artificial Intelligence, 2025.(SCI, 中科院四区). [Paper] [Code]", "image": "assets/publications/paper-17.webp", "imageSource": "https://raw.githubusercontent.com/Yuii666/HADN/master/fig2.png", "imageAlt": "Representative figure from [IJPRAI] He Y, He J, Xue M*, Zhong S, and Zhou M, Hybrid-Domain Attention Dense Network For Efficient Image Super-Resolution, International Journal of Pattern Recognition and Artificial Intelligence, 2025.(SCI, 中科院四区). [Paper] [Code]", "publicationDate": "2025.03", "publicationDateType": "online", "publicationDateSource": "https://api.crossref.org/works/10.1142/s0218001425540035", "abstractEn": "HADN combines dense feature reuse with hybrid-domain attention for efficient image super-resolution. Its attention mechanism strengthens useful structural information and feature interactions, while the dense network accumulates complementary representations. The design balances reconstruction quality with model efficiency.", "abstractZh": "HADN 将密集特征复用与混合域注意力结合，用于高效图像超分辨率重建。注意力机制强化结构信息与特征交互，密集网络累积互补表征，在重建质量与模型效率之间取得平衡。", "title": "Hybrid-Domain Attention Dense Network For Efficient Image Super-Resolution"}, {"year": "2024", "html": "[ESWA] Ning A, Xue M* et al. Artistic-style text detector and a new Movie-Poster dataset. Expert Systems With Applications, 261, 125544.(SCI, 中科院一区). <a href=\"https://www.sciencedirect.com/science/article/pii/S0957417424024114\">[Paper]</a> <a href=\"https://github.com/AXNing/Artistic-style-text-detection\">[Code]</a>", "text": "[ESWA] Ning A, Xue M* et al. Artistic-style text detector and a new Movie-Poster dataset. Expert Systems With Applications, 261, 125544.(SCI, 中科院一区). [Paper] [Code]", "image": "assets/publications/artistic-text-samples.webp", "imageSource": "https://raw.githubusercontent.com/AXNing/Artistic-style-text-detection/main/sample.png", "imageAlt": "Artistic-style — representative results from the authors’ project", "publicationDate": "2025.02", "publicationDateType": "issue", "publicationDateSource": "https://api.crossref.org/works/10.1016/j.eswa.2024.125544", "abstractEn": "This work studies artistic text detection in complex movie posters. A detector combining attention, dense feature representation and boundary discrimination separates stylized text from distracting backgrounds. The Movie-Poster dataset provides 1,500 images to support evaluation of challenging artistic text layouts and appearances.", "abstractZh": "该工作研究复杂电影海报中的艺术风格文本检测。检测器结合注意力、密集特征表征与边界判别，区分风格多样的文本和干扰背景，并构建包含 1,500 张图像的 Movie-Poster 数据集，支持复杂文本布局与外观的评测。", "title": "Artistic-style text detector and a new Movie-Poster dataset"}, {"year": "2024", "html": "[ACML’24] He J, Xue M* et al. Zero-LED: Zero-Reference Lighting Estimation Diffusion Model for Low-Light Image Enhancement. Asian Conference on Machine Learning, Hanoi, Vietnam, 2024  (CCF-C) <a href=\"https://arxiv.org/pdf/2403.02879\">[Paper]</a>", "text": "[ACML’24] He J, Xue M* et al. Zero-LED: Zero-Reference Lighting Estimation Diffusion Model for Low-Light Image Enhancement. Asian Conference on Machine Learning, Hanoi, Vietnam, 2024  (CCF-C) [Paper]", "image": "assets/publications/paper-19.webp", "imageSource": "https://arxiv.org/pdf/2403.02879", "imageAlt": "Representative figure from [ACML’24] He J, Xue M* et al. Zero-LED: Zero-Reference Lighting Estimation Diffusion Model for Low-Light Image Enhancement. Asian Conference on Machine Learning, Hanoi, Vietnam, 2024  (CCF-C) [Paper]", "abstractEn": "Zero-LED enhances low-light images through zero-reference lighting estimation and diffusion. An initial optimization network estimates illumination, while bidirectional constraints and iterative degradation modeling guide recovery. Frequency and semantic information help refine image appearance without requiring normal-light reference images for the enhancement process.", "abstractZh": "Zero-LED 结合零参考光照估计与扩散模型进行低光照增强。初始优化网络估计光照，双向约束与迭代退化建模引导恢复，频率和语义信息进一步细化图像外观，降低增强过程对正常光照参考图像的依赖。", "title": "Zero-LED: Zero-Reference Lighting Estimation Diffusion Model for Low-Light Image Enhancement"}, {"year": "2024", "html": "[ICPR’24] Xie P, He J, Song C and Xue M*. A Novel Encoder-Decoder Network with Multi-domain Information Fusion for Video Deblurring. 27th International Conference on Pattern Recognition, Kolkata, India, 2024. (CCF-C) <a href=\"https://link.springer.com/chapter/10.1007/978-3-031-78125-4_11\">[Paper]</a> <a href=\"https://github.com/Paige-Norton/STFFNet\">[Code]</a>", "text": "[ICPR’24] Xie P, He J, Song C and Xue M*. A Novel Encoder-Decoder Network with Multi-domain Information Fusion for Video Deblurring. 27th International Conference on Pattern Recognition, Kolkata, India, 2024. (CCF-C) [Paper] [Code]", "image": "assets/publications/paper-20.webp", "imageSource": "https://raw.githubusercontent.com/Paige-Norton/STFFNet/main/doc/pic2.png", "imageAlt": "Representative figure from [ICPR’24] Xie P, He J, Song C and Xue M*. A Novel Encoder-Decoder Network with Multi-domain Information Fusion for Video Deblurring. 27th International Conference on Pattern Recognition, Kolkata, India, 2024. (CCF-C) [Paper] [Code]", "publicationDate": "2024.12", "publicationDateType": "online", "publicationDateSource": "https://api.crossref.org/works/10.1007/978-3-031-78125-4_11", "abstractEn": "STFFNet restores blurred video through spatial, temporal and frequency-domain fusion. An encoder–decoder backbone combines global and local features, and a frame-difference-aware fusion module supports current-frame recovery. Frequency-domain conversion further constrains the difference between restored images and reference images.", "abstractZh": "STFFNet 融合空间、时间与频域信息进行视频去模糊。编码器—解码器骨干整合全局与局部特征，关注帧间差异的融合模块辅助当前帧恢复，频域转换进一步缩小恢复图像与参考图像的差距。", "title": "A Novel Encoder-Decoder Network with Multi-domain Information Fusion for Video Deblurring"}, {"year": "2024", "html": "[IEEE SPL] Xue M, He Y, He J, et al. DLDiff: Image Detail-guided Latent Diffusion Model for Low-Light Image Enhancement. IEEE Signal Processing Letters, 2024. (SCI, 中科院二区) <a href=\"https://ieeexplore.ieee.org/document/10663248\">[Paper]</a> <a href=\"https://github.com/Yuii666/DLDiff\">[Code]</a>", "text": "[IEEE SPL] Xue M, He Y, He J, et al. DLDiff: Image Detail-guided Latent Diffusion Model for Low-Light Image Enhancement. IEEE Signal Processing Letters, 2024. (SCI, 中科院二区) [Paper] [Code]", "abstractEn": "DLDiff explores low-light enhancement with a detail-guided latent diffusion model. It performs restoration in a latent representation and incorporates image-detail guidance into the enhancement process. This design focuses on recovering perceptually useful image content while using latent-space modeling for efficient inference.", "abstractZh": "DLDiff 探索基于细节引导的潜空间扩散低光照增强，在潜在表征中进行恢复，并将图像细节引导融入增强过程。该设计关注具有感知价值的内容恢复，同时利用潜空间建模提高推理效率。", "title": "DLDiff: Image Detail-guided Latent Diffusion Model for Low-Light Image Enhancement"}, {"year": "2023", "html": "[Journal of Cloud Computing] Minglong Xue, Yanyi He, Peiqi Xie, Zhengyang He and Xin Feng. “LAE-GAN: a novel cloud-based Low-light Attention Enhancement Generative Adversarial Network for unpaired text images” Journal of Cloud Computing, 12(160), online, 2023 (SCI, 中科院三区) <a href=\"https://link.springer.com/content/pdf/10.1186/s13677-023-00533-4.pdf\">[Paper]</a>", "text": "[Journal of Cloud Computing] Minglong Xue, Yanyi He, Peiqi Xie, Zhengyang He and Xin Feng. “LAE-GAN: a novel cloud-based Low-light Attention Enhancement Generative Adversarial Network for unpaired text images” Journal of Cloud Computing, 12(160), online, 2023 (SCI, 中科院三区) [Paper]", "publicationDate": "2023.11", "publicationDateType": "online", "publicationDateSource": "https://api.crossref.org/works/10.1186/s13677-023-00533-4", "abstractEn": "LAE-GAN provides cloud-based enhancement for unpaired low-light text images. Initial illumination recovery, attention-guided refinement and global/local discrimination support enhancement, while text and edge attention preserve readable structures. The cloud–edge workflow couples server-side enhancement with text detection for practical low-light applications.", "abstractZh": "LAE-GAN 面向非配对低光照文本图像提供云端增强。初始光照恢复、注意力细化及全局与局部判别支持增强，文本和边缘注意力保留可读结构，云边协同流程将服务端增强与文本检测结合。", "title": "LAE-GAN: a novel cloud-based Low-light Attention Enhancement Generative Adversarial Network for unpaired text images"}, {"year": "2023", "html": "[ICIP’23] Minglong Xue, Zhengyang He, Yanyi He, Peiqi Xie and Xin Feng. “UT-GAN: A Novel Unpaired Textual-Attention Generative Adversarial Network for Low-Light Text Image Enhancement” in Proc. International Conference on Image Processing (ICIP). 2023: 1980-1984. (EI, CCF-C) <a href=\"https://ieeexplore.ieee.org/document/10222221\">[Paper]</a>", "text": "[ICIP’23] Minglong Xue, Zhengyang He, Yanyi He, Peiqi Xie and Xin Feng. “UT-GAN: A Novel Unpaired Textual-Attention Generative Adversarial Network for Low-Light Text Image Enhancement” in Proc. International Conference on Image Processing (ICIP). 2023: 1980-1984. (EI, CCF-C) [Paper]", "publicationDate": "2023.10", "publicationDateType": "issue", "publicationDateSource": "https://api.crossref.org/works/10.1109/icip49359.2023.10222221", "abstractEn": "UT-GAN enhances low-light text images without paired supervision. Initial illumination recovery uses Zero-DCE, textual attention emphasizes details within text regions, and an adaptive refinement module reduces noise and adjusts illumination. The method targets a balance between improved lighting and preserved text texture.", "abstractZh": "UT-GAN 在不依赖配对监督的条件下增强低光照文本图像。Zero-DCE 提供初始光照恢复，文本注意力突出文字区域细节，自适应细化模块抑制噪声并调整光照，在亮度改善与文本纹理保留之间取得平衡。", "title": "UT-GAN: A Novel Unpaired Textual-Attention Generative Adversarial Network for Low-Light Text Image Enhancement"}, {"year": "2022", "html": "[ICPR’22] Zhang, Yin, Chengyun Song, and Minglong Xue*. “PSND: A Robust Parking Space Number Detector” in Proc. 2022 26th International Conference on Pattern Recognition (ICPR). IEEE, 2022: 1742-1748. (EI, CCF-C)", "text": "[ICPR’22] Zhang, Yin, Chengyun Song, and Minglong Xue*. “PSND: A Robust Parking Space Number Detector” in Proc. 2022 26th International Conference on Pattern Recognition (ICPR). IEEE, 2022: 1742-1748. (EI, CCF-C)", "publicationDate": "2022.08", "publicationDateType": "issue", "publicationDateSource": "https://api.crossref.org/works/10.1109/icpr56361.2022.9956060"}, {"year": "before 2022", "html": "[TMM’21] Minglong Xue, Palaiahnakote Shivakumara, Chao Zhang, Tong Lu, Umapada Pal, Daniel Lopresti, Zhibo Yang, “Arbitrarily-Oriented Text Detection in Low Light Natural Scene Images” IEEE Transactions on Multimedia, vol. 23, pp. 2706-2720, 2021.(CCF-B, SCI, 中科院一区)", "text": "[TMM’21] Minglong Xue, Palaiahnakote Shivakumara, Chao Zhang, Tong Lu, Umapada Pal, Daniel Lopresti, Zhibo Yang, “Arbitrarily-Oriented Text Detection in Low Light Natural Scene Images” IEEE Transactions on Multimedia, vol. 23, pp. 2706-2720, 2021.(CCF-B, SCI, 中科院一区)"}, {"year": "before 2022", "html": "[ICME’21] Minglong Xue, Zhiheng Huang, Ruo-ze Liu, Tong Lu, “A novel Attention Enhanced Residual-in-Residual dense Networks for Text image Super-resolution” in Proc. International Conference on Multimedia and Expo（ICME）, 2021:1-6. (EI, CCF-B)", "text": "[ICME’21] Minglong Xue, Zhiheng Huang, Ruo-ze Liu, Tong Lu, “A novel Attention Enhanced Residual-in-Residual dense Networks for Text image Super-resolution” in Proc. International Conference on Multimedia and Expo（ICME）, 2021:1-6. (EI, CCF-B)", "publicationDate": "2021.07", "publicationDateType": "issue", "publicationDateSource": "https://api.crossref.org/works/10.1109/icme51207.2021.9428128"}, {"year": "before 2022", "html": "[MAT’19] Minglong Xue, Palaiahnakote Shivakumara, Chao Zhang, Yao Xiao, Tong Lu, Umapada Pal, Michael Blumenstein, Daniel Lopresti, “Curved text detection in blurred/non-blurred video/scene images” pp. 25629- 25653, 2019. (CCF-C, SCI,中科院三区 )", "text": "[MAT’19] Minglong Xue, Palaiahnakote Shivakumara, Chao Zhang, Yao Xiao, Tong Lu, Umapada Pal, Michael Blumenstein, Daniel Lopresti, “Curved text detection in blurred/non-blurred video/scene images” pp. 25629- 25653, 2019. (CCF-C, SCI,中科院三区 )", "publicationDate": "2019.05", "publicationDateType": "online", "publicationDateSource": "https://api.crossref.org/works/10.1007/s11042-019-7721-2"}, {"year": "before 2022", "html": "[ICDAR’19] Yao Xiao, Minglong Xue, Tong Lu, Yirui Wu, Palaiahnakote Shivakumara, “A text-context-aware CNN network for multi-oriented and multi-language scene text detection” in Proc. 2019 International Conference on Document Analysis and Recognition (ICDAR), pp. 695-700, 2019. (EI, CCF-C)", "text": "[ICDAR’19] Yao Xiao, Minglong Xue, Tong Lu, Yirui Wu, Palaiahnakote Shivakumara, “A text-context-aware CNN network for multi-oriented and multi-language scene text detection” in Proc. 2019 International Conference on Document Analysis and Recognition (ICDAR), pp. 695-700, 2019. (EI, CCF-C)", "publicationDate": "2019.09", "publicationDateType": "issue", "publicationDateSource": "https://api.crossref.org/works/10.1109/icdar.2019.00116"}, {"year": "before 2022", "html": "[PCM’19] Chao Zhang, Palaiahnakote Shivakumara, Minglong Xue, Liping Zhu, Tong Lu, Umapada Pal, “New fusion based enhancement for text detection in night video footage” in Proc. 2018 Pacific Rim Conference on Multimedia (PCM). pp. 46-56, 2018. (EI, CCF-C)", "text": "[PCM’19] Chao Zhang, Palaiahnakote Shivakumara, Minglong Xue, Liping Zhu, Tong Lu, Umapada Pal, “New fusion based enhancement for text detection in night video footage” in Proc. 2018 Pacific Rim Conference on Multimedia (PCM). pp. 46-56, 2018. (EI, CCF-C)", "publicationDate": "2018.09", "publicationDateType": "online", "publicationDateSource": "https://api.crossref.org/works/10.1007/978-3-030-00764-5_5"}], "students": [{"begin": "2026", "name": "Xingyue Liu", "end": "2029"}, {"begin": "2026", "name": "Kui Liu", "end": "2029"}, {"begin": "2026", "name": "Gaoyu Liu", "end": "2029"}, {"begin": "2026", "name": "Guodong Cai", "end": "2029"}, {"begin": "2026", "name": "Hongxu Chen", "end": "2029"}, {"begin": "2026", "name": "Guoan Guan", "end": "2029"}, {"begin": "2025", "name": "Yi Qu", "end": "2028"}, {"begin": "2025", "name": "Xiaoru Gao", "end": "2028"}, {"begin": "2025", "name": "Xukun Shang", "end": "2028"}, {"begin": "2025", "name": "Xukang Wang", "end": "2028"}, {"begin": "2024", "name": "Jianfeng Fu", "end": "2027"}, {"begin": "2024", "name": "Wenchao Yan", "end": "2027"}, {"begin": "2024", "name": "Kaiwen Chen", "end": "2027"}, {"begin": "2023", "name": "Aoxiang Ning", "end": "2026"}, {"begin": "2023", "name": "Jinhong He", "end": "2026"}, {"begin": "2023", "name": "Shuaibin Fan", "end": "2026"}, {"begin": "2022", "name": "Peiqi Xie", "end": "2025"}, {"begin": "2022", "name": "Yanyi He", "end": "2025"}, {"begin": "2021", "name": "Zhengyang He", "end": "2024"}], "scholar": "https://scholar.google.com.hk/citations?hl=zh-CN&user=HgX9lPoAAAAJ", "manuscripts": "<p>No additional manuscripts are currently listed.</p>", "honors": "<ul>\n<li><em>2023</em> Shiji Scholar of Chongqing University of Technology (重庆理工大学士继英才·青年拔尖)</li>\n</ul>"};
